const listAgents = `-- name: ListAgents :many
SELECT agent_id, tenant_id, agent_name, status, auth_version,
       created_at_ns, updated_at_ns, disabled_at_ns
FROM agents
WHERE tenant_id = ?1
  AND (cast(?2 AS text) = ''
       OR substr(agent_name, 1, length(cast(?2 AS text))) = cast(?2 AS text))
  AND (cast(?3 AS text) = ''
       OR agent_name > cast(?3 AS text)
       OR (agent_name = cast(?3 AS text)
           AND agent_id > cast(?4 AS text)))
ORDER BY agent_name, agent_id
LIMIT cast(?5 AS integer)
`

type ListAgentsParams struct {
	TenantID   string
	NamePrefix string
	AfterName  string
	AfterID    string
	PageLimit  int64
}

type ListAgentsRow struct {
	AgentID      string
	TenantID     string
	AgentName    string
	Status       int64
	AuthVersion  int64
	CreatedAtNs  int64
	UpdatedAtNs  int64
	DisabledAtNs sql.NullInt64
}

func (q *Queries) ListAgents(ctx context.Context, arg ListAgentsParams) ([]ListAgentsRow, error) {
	rows, err := q.db.QueryContext(ctx, listAgents,
		arg.TenantID,
		arg.NamePrefix,
		arg.AfterName,
		arg.AfterID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAgentsRow{}
	for rows.Next() {
		var i ListAgentsRow
		if err := rows.Scan(
			&i.AgentID,
			&i.TenantID,
			&i.AgentName,
			&i.Status,
			&i.AuthVersion,
			&i.CreatedAtNs,
			&i.UpdatedAtNs,
			&i.DisabledAtNs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

